import {styleText,blockHTML,esc} from './cms/runtime.mjs';
const json=(v,s=200)=>new Response(JSON.stringify(v),{status:s,headers:{'Content-Type':'application/json','Cache-Control':'no-store'}});
const pathOK=p=>typeof p==='string'&&/^\/satin(?:\/[a-z0-9-]+)*\/?$/.test(p)&&p.length<240;
const empty=()=>({edits:[],order:[],fields:[],blocks:[],sections:[],sectionOrder:[],seo:{}});
const nums={fontSize:[10,160],width:[5,100],height:[20,2000],borderRadius:[0,200],objectPosition:[0,100],padding:[0,200],opacity:[0,1]};
function style(s={}){if(!s||typeof s!=='object'||Array.isArray(s))throw Error('Invalid appearance');const o={};for(const [k,v]of Object.entries(s)){if(nums[k]){if(!Number.isFinite(v)||v<nums[k][0]||v>nums[k][1])throw Error('Check '+k);o[k]=v;}else if(['color','backgroundColor'].includes(k)&&/^#[a-f0-9]{6}$/i.test(v))o[k]=v;else if(k==='textAlign'&&['left','center','right','justify','start'].includes(v)||k==='fontWeight'&&['400','500','600','700','800','900'].includes(String(v))||k==='objectFit'&&['cover','contain','fill'].includes(v)||k==='fontFamily'&&['inherit','Arial','Georgia','Verdana','Tahoma','sans-serif','serif'].includes(v))o[k]=v;else throw Error('Invalid appearance');}return o;}
const linkOK=v=>typeof v==='string'&&v.length<=1000&&(/^(\/satin(?:\/|$)|https:\/\/|mailto:|tel:)/.test(v))&&!/[<>"\s]/.test(v);
const imageOK=v=>typeof v==='string'&&(/^\/satin\/img\/[a-zA-Z0-9_.-]+$/.test(v)||/^\/satin\/portfolio\/images\/[a-z0-9_.-]+$/.test(v)||/^\/api\/product-image\?id=[a-f0-9-]{36}$/.test(v));
export async function readContent(env,path,draft=false){const key=path.replace(/\/$/,'');const r=await env.DB.prepare('SELECT value FROM site_settings WHERE key = ?').bind('builder:'+key).first();if(r){const d=JSON.parse(r.value);return {...(draft?d.draft:d.published)||empty(),revision:d.revision,updatedAt:d.updatedAt};}const legacy=await env.DB.prepare('SELECT value,updated_at FROM site_settings WHERE key = ?').bind((draft?'draft:':'published:')+key).first();return {...(legacy?JSON.parse(legacy.value):empty()),revision:0,updatedAt:legacy?.updated_at||null};}
export async function contentRoutes(request,env,url,isAdmin){if(!['/api/site-content','/api/admin/content'].includes(url.pathname))return null;const owner=url.pathname.startsWith('/api/admin/');if(owner&&!isAdmin(request))return json({error:'Owner sign-in required'},403);if(!env.DB)return json({error:'Website editing unavailable'},503);if(request.method==='GET'){const p=url.searchParams.get('path');if(!pathOK(p))return json({error:'Invalid page'},400);return json(await readContent(env,p,owner));}if(!owner||request.method!=='POST')return json({error:'Method not allowed'},405);if(request.headers.get('Origin')!==url.origin)return json({error:'Invalid request origin'},403);
try{const raw=await request.text();if(raw.length>250000)throw Error('Page too large');const v=JSON.parse(raw);if(!pathOK(v.path))throw Error('Invalid page');const p=v.path.replace(/\/$/,''),prior=await readContent(env,p,true);if(v.revision!==undefined&&v.revision!==prior.revision)return json({error:'This page changed in another window. Reload it before saving.'},409);if(!Array.isArray(v.edits)||v.edits.length>500||!Array.isArray(v.fields)||v.fields.length>20)throw Error('Invalid page changes');const value={...empty(),...prior};delete value.updatedAt;delete value.revision;
value.edits=v.edits.map(e=>{if(!e||typeof e.selector!=='string'||e.selector.length>1000||!(/^#main[ >a-zA-Z0-9:()._-]*$/.test(e.selector)||/^#main \[data-cms-id="(?:e\d+|b[a-f0-9-]+-(?:title|body|image))"\]$/.test(e.selector))||!['text','image'].includes(e.type)||typeof e.value!=='string'||e.value.length>5000||e.type==='image'&&!imageOK(e.value))throw Error('Invalid text or image');if(e.link!==undefined&&e.link!==''&&!linkOK(e.link))throw Error('Check link');return {selector:e.selector,type:e.type,value:e.value,...(e.alt!==undefined?{alt:String(e.alt).slice(0,300)}:{}),...(e.style?{style:style(e.style)}:{}),...(e.mobile?{mobile:style(e.mobile)}:{}),...(e.link?{link:e.link}:{}),hidden:!!e.hidden};});
value.fields=v.fields;if(v.fields.some(f=>!f||!/^[a-z0-9_-]{1,40}$/.test(f.key)||typeof f.label!=='string'||!f.label.trim()||f.label.length>120||!['text','email','number','textarea'].includes(f.type)||typeof f.required!=='boolean')||new Set(v.fields.map(f=>f.key)).size!==v.fields.length)throw Error('Check form fields');
if(v.order!==undefined){if(!Array.isArray(v.order)||v.order.length>150||v.order.some(i=>!Number.isInteger(i)||i<0||i>150)||new Set(v.order).size!==v.order.length)throw Error('Invalid sections');value.order=v.order;}
if(v.blocks!==undefined){if(!Array.isArray(v.blocks)||v.blocks.length>30)throw Error('Use up to 30 new sections');value.blocks=v.blocks.map(b=>{if(!/^b[a-f0-9-]{36}$/.test(b.id)||!['text','image','text-image'].includes(b.kind)||b.image&&!imageOK(b.image)||b.link&&!linkOK(b.link))throw Error('Invalid new section');return {id:b.id,kind:b.kind,title:String(b.title||'').slice(0,200),body:String(b.body||'').slice(0,5000),image:b.image||'',alt:String(b.alt||'').slice(0,300),link:b.link||'',button:String(b.button||'').slice(0,80),style:style(b.style)};});if(new Set(value.blocks.map(b=>b.id)).size!==value.blocks.length)throw Error('Duplicate sections');}
if(v.sectionOrder!==undefined){if(!Array.isArray(v.sectionOrder)||v.sectionOrder.length>180||v.sectionOrder.some(id=>!/^s\d+$|^b[a-f0-9-]{36}$/.test(id))||new Set(v.sectionOrder).size!==v.sectionOrder.length)throw Error('Invalid section order');value.sectionOrder=v.sectionOrder;}
if(v.sections!==undefined){if(!Array.isArray(v.sections)||v.sections.length>180)throw Error('Invalid sections');value.sections=v.sections.map(s=>{if(!/^s\d+$|^b[a-f0-9-]{36}$/.test(s.id))throw Error('Invalid section');return {id:s.id,style:style(s.style),hidden:!!s.hidden};});}
if(v.seo!==undefined)value.seo={title:String(v.seo.title||'').slice(0,100),description:String(v.seo.description||'').slice(0,320),...(v.seo.noindex!==undefined?{noindex:!!v.seo.noindex}:{})};
for(const src of [...value.edits.filter(e=>e.type==='image').map(e=>e.value),...value.blocks.map(b=>b.image)].filter(Boolean)){if(src.startsWith('/api/')&&!await env.FILES?.head('products/'+src.split('=')[1]))throw Error('Upload this image first');if(src.startsWith('/satin/')&&!(await env.ASSETS.fetch(new Request(new URL(src,url)))).ok)throw Error('Image not found');}
const existing=await env.DB.prepare('SELECT value FROM site_settings WHERE key = ?').bind('builder:'+p).first();let prev=existing?JSON.parse(existing.value):{revision:0,published:await readContent(env,p)};if(prev.revision!==prior.revision)return json({error:'The page changed. Reload before saving.'},409);const now=new Date().toISOString(),doc={revision:prev.revision+1,updatedAt:now,draft:value,published:v.publish?value:prev.published};const result=existing?await env.DB.prepare('UPDATE site_settings SET value = ?, updated_at = ? WHERE key = ? AND value = ?').bind(JSON.stringify(doc),now,'builder:'+p,existing.value).run():await env.DB.prepare('INSERT INTO site_settings (key,value,updated_at) VALUES (?,?,?) ON CONFLICT(key) DO NOTHING').bind('builder:'+p,JSON.stringify(doc),now).run();if(!result.meta.changes)return json({error:'The page changed. Reload before saving.'},409);
if(v.publish)await env.DB.prepare('INSERT INTO site_settings (key,value,updated_at) VALUES (?,?,?) ON CONFLICT(key) DO UPDATE SET value=excluded.value,updated_at=excluded.updated_at').bind('published:'+p,JSON.stringify(value),now).run();return json({saved:true,revision:doc.revision,updatedAt:now,published:!!v.publish});
}catch(e){console.error('Website content rejected',e.message);return json({error:e.message||'Could not save page'},400);}}
export async function publishedImage(env,src){const rs=await env.DB.prepare("SELECT value FROM site_settings WHERE key LIKE 'builder:%'").all();return rs.results.some(r=>{const c=JSON.parse(r.value).published;return c?.edits?.some(e=>e.type==='image'&&e.value===src)||c?.blocks?.some(b=>b.image===src);});}
// Static pages contain stable element and section IDs. Render published edits before returning HTML to crawlers.
export async function renderContent(response,request,env){if(!response.ok||!response.headers.get('Content-Type')?.includes('text/html')||!env.DB)return response;const url=new URL(request.url);if(!pathOK(url.pathname))return response;let c;try{c=await readContent(env,url.pathname);}catch{return response;}let html=await response.text();if(new URLSearchParams(url.search).has('cms')){const h=new Headers(response.headers);h.set('Cache-Control','no-store');h.set('X-Robots-Tag','noindex, nofollow');return new Response(html,{status:response.status,headers:h});}
const blocks=(c.blocks||[]).map(blockHTML).join('');if(blocks)html=html.replace(/(<\/div>\s*<\/main>)/,blocks+'$1');
for(const e of c.edits||[]){const id=e.selector.match(/data-cms-id="([\w-]+)"/)?.[1];if(!id)continue;const re=new RegExp('(<(h[1-4]|p|img|a|b|span|button)\\b[^>]*data-cms-id="'+id+'"[^>]*>)([\\s\\S]*?</\\2>)?');html=html.replace(re,(match,open,tag,rest)=>{let attrs=open;if(e.link&&tag==='a')attrs=attrs.replace(/\shref="[^"]*"/g,'').slice(0,-1)+' href="'+esc(e.link)+'">';if(e.style){const before=attrs.match(/\sstyle="([^"]*)"/)?.[1]||'';attrs=attrs.replace(/\sstyle="([^"]*)"/g,'');attrs=attrs.slice(0,-1)+' style="'+before+';'+esc(styleText(e.style)+(e.type==='image'&&e.style.height===undefined?';height:auto':''))+'"'+(e.hidden?' hidden':'')+'>';}if(e.type==='image'&&tag==='img'){attrs=attrs.replace(/\s(?:src|srcset|alt)="[^"]*"/g,'');return attrs.slice(0,-1)+' src="'+esc(e.value)+'" alt="'+esc(e.alt||'')+'">';}if(e.type==='text')attrs=attrs.replace(/\sdata-count="[^"]*"/g,'');return attrs+(e.type==='text'?esc(e.value)+'</'+tag+'>':rest||'');});}
html=html.replace(/<picture\b[^>]*>([\s\S]*?)<\/picture>/g,(m,inner)=>{const changed=(c.edits||[]).some(e=>e.type==='image'&&inner.includes(e.selector.match(/data-cms-id="([\w-]+)"/)?.[0]||'__none__'));return changed?m.replace(/<source\b[^>]*>/g,''):m;});

html=reorderSections(html,c.sectionOrder);
const css=[...(c.sections||[]).map(s=>`#main [data-cms-section="${s.id}"]{${styleText(s.style)};${s.hidden?'display:none;':''}}`),...(c.edits||[]).filter(e=>e.hidden).map(e=>e.selector+'{display:none}')].join('');const mobile=(c.edits||[]).filter(e=>e.mobile).map(e=>e.selector+'{'+styleText(e.mobile).split(';').filter(Boolean).map(d=>d+'!important').join(';')+'}').join('');if(css||mobile)html=html.replace('</head>',`<style id="cms-server-styles">${css}@media(max-width:700px){${mobile}}</style></head>`);
if(c.seo?.title){html=html.replace(/<title>[\s\S]*?<\/title>/,()=>'<title>'+esc(c.seo.title)+'</title>').replace(/(<meta\s(?:property|name)="(?:og:title|twitter:title)"\scontent=")[^"]*/g,(_,a)=>a+esc(c.seo.title));}if(c.seo?.description)html=html.replace(/(<meta\s(?:property|name)="(?:description|og:description|twitter:description)"\scontent=")[^"]*/g,(_,a)=>a+esc(c.seo.description));if(c.seo?.noindex!==undefined)html=html.replace(/(<meta name="robots" content=")[^"]*/,(_,a)=>a+(c.seo.noindex?'noindex,follow':'index,follow'));
html=html.replace(/(<script type="application\/ld\+json" id="page-schema">)([\s\S]*?)(<\/script>)/,(_m,a,data,b)=>{try{const schema=JSON.parse(data);for(const g of schema['@graph']||[])if(['Service','CollectionPage','CreativeWork','Product'].includes(g['@type'])){if(c.seo?.description)g.description=c.seo.description;if(c.seo?.title&&['Service','CollectionPage'].includes(g['@type']))g.name=c.seo.title;}return a+JSON.stringify(schema).replace(/</g,'\\u003c')+b;}catch{return _m;}});
const h=new Headers(response.headers);h.set('Cache-Control','no-store');h.delete('Content-Length');return new Response(html,{status:response.status,headers:h});}
function reorderSections(html,order){if(!order?.length)return html;const start=html.match(/<div[^>]*class="page-enter"[^>]*>/);if(!start)return html;const offset=start.index+start[0].length;const tail=html.slice(offset);const tokens=/<\/?([a-z0-9]+)\b[^>]*>/gi;let depth=0,begin=0,end=0,sections=[],m;const voids=new Set(['img','source','input','br','hr','area','base','col','embed','link','meta','param','track','wbr']);while((m=tokens.exec(tail))){const closing=m[0].startsWith('</'),name=m[1].toLowerCase();if(closing&&depth===0){end=m.index;break;}if(!closing){if(depth===0)begin=m.index;if(!voids.has(name)&&!m[0].endsWith('/>'))depth++;else if(depth===0)sections.push(tail.slice(begin,tokens.lastIndex));}else{depth--;if(depth===0)sections.push(tail.slice(begin,tokens.lastIndex));}}if(!end)return html;const entries=sections.map(s=>({html:s,id:s.match(/data-cms-section="([^"]+)"/)?.[1]}));const ordered=order.map(id=>entries.find(e=>e.id===id)).filter(Boolean);entries.filter(e=>!order.includes(e.id)).forEach(e=>ordered.push(e));return html.slice(0,offset)+ordered.map(e=>e.html).join('')+tail.slice(end);}
